mapper.select:
select count(*)
from content_items
where id = #{contentId}

select count(*)
from users
where id = #{userId}

mapper.update:
update content_stats
set like_count = like_count + 1
where content_id = #{contentId}

update content_stats
set like_count = case when like_count > 0 then like_count - 1 else 0 end
where content_id = #{contentId}

mapper.select:
select count(*)
from collection_items item
join collections collection on collection.id = item.collection_id
where item.content_id = #{contentId}
  and collection.user_id = #{userId}
  and collection.is_default = true

mapper.update:
update content_stats
set favorite_count = favorite_count + 1
where content_id = #{contentId}

update content_stats
set favorite_count = case when favorite_count > 0 then favorite_count - 1 else 0 end
where content_id = #{contentId}

mapper.select:
select id, content_id
from comments
where id = #{commentId}

mapper.update:
update comments
set like_count = like_count + 1
where id = #{commentId}

mapper.select:
select content_id, like_count, comment_count, favorite_count, share_count, view_count
from content_stats
where content_id = #{contentId}
